namespace sv_fa084804ce8847d1bd54647f71d313a7.Services;

public enum ThemeMode
{
    Light,
    Dark,
    System
}

/// <summary>
/// Scoped service holding per-circuit theme state.
/// Components subscribe to OnChange to react when any component mutates theme values.
/// </summary>
public sealed class ThemeService
{
    private ThemeMode _theme = ThemeMode.System;
    private string _accentColor = "#0d6efd";

    public ThemeMode Theme => _theme;
    public string AccentColor => _accentColor;

    /// <summary>
    /// Fired whenever theme or accent color changes.
    /// Subscribers should call StateHasChanged (on the sync context) when this fires.
    /// </summary>
    public event Action? OnChange;

    public void SetTheme(ThemeMode theme)
    {
        if (_theme == theme) return;
        _theme = theme;
        NotifyStateChanged();
    }

    public void SetAccentColor(string color)
    {
        if (_accentColor == color) return;
        _accentColor = color;
        NotifyStateChanged();
    }

    public void SetAll(ThemeMode theme, string accentColor)
    {
        var changed = _theme != theme || _accentColor != accentColor;
        _theme = theme;
        _accentColor = accentColor;
        if (changed) NotifyStateChanged();
    }

    private void NotifyStateChanged() => OnChange?.Invoke();
}

@rendermode InteractiveServer
@using sv_fa084804ce8847d1bd54647f71d313a7.Services
@inject ThemeService ThemeSvc
@implements IDisposable

<span class="theme-indicator" style="color: @ThemeSvc.AccentColor;" title="Current theme">
    @GetIcon() @ThemeSvc.Theme
</span>

@code {
    protected override void OnInitialized()
    {
        ThemeSvc.OnChange += HandleThemeChanged;
    }

    private void HandleThemeChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    private string GetIcon() => ThemeSvc.Theme switch
    {
        ThemeMode.Light => "☀️",
        ThemeMode.Dark => "🌙",
        _ => "💻"
    };

    public void Dispose()
    {
        ThemeSvc.OnChange -= HandleThemeChanged;
    }
}

@page "/settings"
@rendermode InteractiveServer
@using sv_fa084804ce8847d1bd54647f71d313a7.Services
@inject ThemeService ThemeSvc
@implements IDisposable

<PageTitle>Settings</PageTitle>

<h1>User Preferences</h1>

<div class="mb-3">
    <label class="form-label">Theme</label>
    <select class="form-select" style="max-width:200px"
            value="@ThemeSvc.Theme"
            @onchange="OnThemeSelected">
        @foreach (var mode in Enum.GetValues<ThemeMode>())
        {
            <option value="@mode">@mode</option>
        }
    </select>
</div>

<div class="mb-3">
    <label class="form-label">Accent Color</label>
    <input type="color" class="form-control form-control-color"
           value="@ThemeSvc.AccentColor"
           @onchange="OnAccentChanged" />
</div>

<div class="mt-4 p-3 border rounded" style="border-color: @ThemeSvc.AccentColor !important;">
    <strong>Preview:</strong> Current theme is <em>@ThemeSvc.Theme</em>
    with accent <span style="color:@ThemeSvc.AccentColor;">@ThemeSvc.AccentColor</span>
</div>

@code {
    protected override void OnInitialized()
    {
        ThemeSvc.OnChange += HandleThemeChanged;
    }

    private void OnThemeSelected(ChangeEventArgs e)
    {
        if (Enum.TryParse<ThemeMode>(e.Value?.ToString(), out var mode))
        {
            ThemeSvc.SetTheme(mode);
        }
    }

    private void OnAccentChanged(ChangeEventArgs e)
    {
        ThemeSvc.SetAccentColor(e.Value?.ToString() ?? "#0d6efd");
    }

    private void HandleThemeChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        ThemeSvc.OnChange -= HandleThemeChanged;
    }
}

